class Solution {
public:
    bool isPrefixString(string s, vector<string>& words) {
        int i = 0;
        int n = (int)s.length();
        for (const string& w : words) {
            int wl = (int)w.length();
            if (i + wl > n) return false;
            for (int j = 0; j < wl; j++) {
                if (s[i + j] != w[j]) return false;
            }
            i += wl;
            if (i == n) return true;
        }
        return false;
    }
};
